const keys = Array.isArray(args) && args.length ? args : Object.keys(TOPICS)
const selected = keys.filter(k => TOPICS[k]).map(k => ({ key: k, ...TOPICS[k] }))
log(`Topics in this run: ${selected.map(t => t.key).join(', ')}`)

const notesPath = (t, a) => `${ROOT}/docs/research/notes/${t.key}.${a.key}.md`
const docPath = t => `${ROOT}/docs/research/${t.file}`

const results = await pipeline(
  selected,
  // Stage 1 — independent researchers (barrier per topic only: synthesis needs all angles of THIS topic)
  async t => {
    phase('Research')
    const summaries = await parallel(t.angles.map(a => () => agent(
      `${CONTEXT}\nYou are a meticulous research analyst. Topic: "${t.title}".\n${a.brief}\n${RULES}\n` +
      `OUTPUT: write your full research notes (aim for 1500-3500 words of dense, sourced findings, tables welcome) to the file ${notesPath(t, a)} using the Write tool. ` +
      `End the notes with a "Sources" list and a "Could not verify" list. Then reply with a 10-line plain summary of your key findings and the biggest uncertainties.`,
      { label: `research:${t.key}:${a.key}`, phase: 'Research' })))
    return summaries.map((s, i) => `### ${t.angles[i].key}\n${s || '(researcher failed — notes file may be missing)'}`).join('\n\n')
  },
  // Stage 2 — synthesis
  async (summ, t) => {
    await agent(
      `${CONTEXT}\nYou are the lead analyst writing the reference document on: "${t.title}".\n` +
      `Read ALL of these researcher notes files in full first: ${t.angles.map(a => notesPath(t, a)).join(' , ')} (if one is missing, proceed with the others and do your own searches to fill that angle).\n` +
      `Researcher summaries for orientation:\n${summ}\n\n${t.synth}\n${RULES}\n` +
      `You may run additional WebSearch queries to fill gaps or resolve contradictions between the notes. Keep every source link and confidence marker ([V2]/[V1]/[M]) from the notes; do not upgrade a marker without new evidence. ` +
      `Resolve contradictions explicitly ("A says X, B says Y; we keep X because..."). Be concrete and decision-oriented; no filler.\n` +
      `End the document with a section "## Implications for the implementation" — a numbered list of concrete, actionable requirements for the code (crate names are not needed; state behaviours, defaults, numbers).\n` +
      `OUTPUT: write the document to ${docPath(t)} (Markdown, start with "# ${t.title}", then a line "_Status: draft — research date 2026-11-12_"). Reply with only "written".`,
      { label: `synthesize:${t.key}`, phase: 'Synthesize' })
    return true
  },
  // Stage 3 — adversarial fact-check
  async (_ok, t) => {
    const report = await agent(
      `${CONTEXT}\nYou are an adversarial fact-checker. A colleague wrote ${docPath(t)} ("${t.title}"). Read it in full. Your job is to find what is WRONG, outdated, overstated or unsupported — not to praise it.\n` +
      `1) List the 20 most load-bearing claims (numbers, prices, legal statements, licence terms, capabilities, "X supports Y") — the ones that would hurt most if wrong. ` +
      `2) Re-verify each with fresh, independent WebSearch queries (do not reuse the document's own wording as the query; use mode "extended" for prices and recent facts). ` +
      `3) Also hunt for important things the document MISSED (a major source, a 2025-2026 change, a counter-example, a contrary court decision).\n` +
      `WebFetch is blocked in this sandbox; use WebSearch only. Never invent URLs. Do not edit the document.\n` +
      `Return a report: for each checked claim -> verdict CONFIRMED / WRONG / OUTDATED / UNSUPPORTED / PARTLY, the corrected statement, and source URLs; then a list of omissions with sources; then a list of statements that should be downgraded to "unverified". Default to UNSUPPORTED when you cannot find evidence.`,
      { label: `fact-check:${t.key}`, phase: 'Fact-check' })
    return report || '(fact-checker failed)'
  },
  // Stage 4 — finalize
  async (report, t) => {
    const out = await agent(
      `${CONTEXT}\nYou are the editor finalising ${docPath(t)} ("${t.title}"). An adversarial fact-checker produced the report below.\n` +
      `Apply it: fix every WRONG/OUTDATED claim in place, soften or mark UNSUPPORTED ones as unverified, add the omissions (with their sources), and keep the document coherent (update the executive summary and the "Implications for the implementation" section if conclusions changed). ` +
      `If a correction looks doubtful you may run a WebSearch to arbitrate. Change the status line to "_Status: fact-checked — research date 2026-11-12_". ` +
      `Append a section "## Verification log" summarising what was checked, what was corrected, and what remains unverified.\n` +
      `Use the Edit/Write tools on that one file only; no git.\n\nFACT-CHECK REPORT:\n${report}\n\n` +
      `When done, reply with: (1) a 12-line summary of the document's final conclusions, and (2) the full text of its "Implications for the implementation" section.`,
      { label: `finalize:${t.key}`, phase: 'Finalize' })
    return { topic: t.key, file: docPath(t), summary: out }
  },
)

return results.filter(Boolean)
